class Animation:
    """Represents a sequence of frames to be shown on the OLED display."""

    def __init__(self, frames, width=FRAME_WIDTH, height=FRAME_HEIGHT, delay_ms=FRAME_DELAY_MS):
        self.frames = frames
        self.width = width
        self.height = height
        self.delay_ms = delay_ms
        self.frame_index = 0

    def next_frame(self):
        """Return current frame FrameBuffer and advance to next frame."""
        data = self.frames[self.frame_index]
        fb = framebuf.FrameBuffer(bytearray(data), self.width, self.height, framebuf.MONO_HLSB)
        self.frame_index = (self.frame_index + 1) % len(self.frames)
        return fb

    def play_once(self, oled, x=40, y=8, should_stop=None):
        """Blit every frame once onto the given oled display, unless `should_stop()` returns True."""
        for _ in range(len(self.frames)):
            if should_stop and should_stop():
                break
            fb = self.next_frame()
            oled.blit(fb, x, y)
            oled.show()
            time.sleep_ms(self.delay_ms)

    def play_loop(self, oled, x=40, y=8, iterations=None, should_stop=None):
        """Loop the animation forever, or `iterations` times if given, until `should_stop()` returns True."""
        count = 0
        while iterations is None or count < iterations:
            if should_stop and should_stop():
                break
            self.play_once(oled, x, y, should_stop=should_stop)
            count += 1

    def stop(self, oled, x=40, y=8, clear_full_screen=False):
        """Erase the animation area (or the whole screen) and reset playback to the first frame."""
        if clear_full_screen:
            oled.fill(0)
        else:
            oled.fill_rect(x, y, self.width, self.height, 0)
        oled.show()
        self.frame_index = 0

CIRCLES_MENU_3 = Animation(CIRCLE_LOADING_FRAMES)